import bisect
from collections import deque
import threading
import time
from typing import Optional


class SlidingWindowRateLimiter:
    """Thread-safe sliding window rate limiter."""

    def __init__(self, max_requests: int, window_seconds: float) -> None:
        if max_requests < 0:
            raise ValueError("max_requests must be non-negative")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be positive")

        self.max_requests: int = int(max_requests)
        self.window_seconds: float = float(window_seconds)
        self._requests: dict[str, deque[float]] = {}
        self._lock = threading.RLock()

    def _evict_expired(self, queue: deque[float], now: float) -> None:
        cutoff = now - self.window_seconds
        while queue and (queue[0] <= cutoff or queue[0] + self.window_seconds <= now):
            queue.popleft()

    def allow_request(
        self, key: str, timestamp: Optional[float] = None
    ) -> tuple[bool, float]:
        now = time.time() if timestamp is None else float(timestamp)
        with self._lock:
            if self.max_requests == 0:
                return False, self.window_seconds

            queue = self._requests.get(key)
            if queue is None:
                queue = deque()
                self._requests[key] = queue
            else:
                self._evict_expired(queue, now)

            if len(queue) < self.max_requests:
                if not queue or now >= queue[-1]:
                    queue.append(now)
                else:
                    bisect.insort(queue, now)
                return True, 0.0

            retry_after = (queue[0] + self.window_seconds) - now
            return False, max(0.0, float(retry_after))

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        now = time.time() if timestamp is None else float(timestamp)
        with self._lock:
            if self.max_requests == 0:
                return 0

            queue = self._requests.get(key)
            if queue is None:
                return self.max_requests

            self._evict_expired(queue, now)
            if not queue:
                del self._requests[key]
                return self.max_requests

            return max(0, self.max_requests - len(queue))
