from __future__ import annotations

import asyncio
import contextvars
from dataclasses import dataclass, field
import inspect
import itertools
from typing import Any, Awaitable, Callable, Dict, List, Optional, Set, Tuple

_current_pool: contextvars.ContextVar[Optional["AsyncWorkerPool"]] = (
    contextvars.ContextVar("_current_pool", default=None)
)


@dataclass(order=True)
class _WorkItem:
    sort_index: Tuple[Any, int]
    coro_func: Callable[..., Awaitable[Any]] = field(compare=False)
    args: Tuple[Any, ...] = field(compare=False)
    kwargs: Dict[str, Any] = field(compare=False)
    future: asyncio.Future = field(compare=False)


class AsyncWorkerPool:
    """Asynchronous worker pool with priority queueing and graceful/immediate shutdown."""

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency <= 0:
            raise ValueError("concurrency must be greater than 0")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be non-negative")

        self.concurrency: int = concurrency
        self.max_queue_size: int = max_queue_size
        self._concurrency: int = concurrency
        self._max_queue_size: int = max_queue_size

        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(
            maxsize=max_queue_size
        )
        self._counter = itertools.count()
        self._workers: List[asyncio.Task] = []
        self._ephemeral_workers: Set[asyncio.Task] = set()
        self._idle_workers: Set[asyncio.Task] = set()
        self._active_tasks: Set[asyncio.Task] = set()
        self._pending_puts: Set[asyncio.Task] = set()
        self._tracked_futures: Set[asyncio.Future] = set()

        self._started: bool = False
        self._shutting_down: bool = False
        self._stop_workers: bool = False
        self._aborting: bool = False
        self._shutdown_done: Optional[asyncio.Event] = None

    async def start(self) -> None:
        """Spawns worker tasks for the pool."""
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")
        if self._started:
            return
        self._started = True
        self._workers = [
            asyncio.create_task(self._worker(i), name=f"AsyncWorkerPool-worker-{i}")
            for i in range(self._concurrency)
        ]

    async def submit(
        self,
        coro_func: Callable[..., Awaitable[Any]],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        """Enqueues a coroutine function to be executed by the pool workers.

        Higher priority integers execute before lower priority integers.
        Returns an asyncio.Future resolving with the task result or exception.
        """
        if self._shutting_down:
            if inspect.iscoroutine(coro_func):
                coro_func.close()
            raise RuntimeError("Pool is shutting down")

        if not callable(coro_func) and not inspect.iscoroutine(coro_func):
            raise TypeError("coro_func must be a coroutine function or callable")

        loop = asyncio.get_running_loop()
        future: asyncio.Future = loop.create_future()
        item = _WorkItem(
            sort_index=(-priority, next(self._counter)),
            coro_func=coro_func,
            args=args,
            kwargs=kwargs,
            future=future,
        )

        self._tracked_futures.add(future)
        future.add_done_callback(self._tracked_futures.discard)

        is_reentrant = _current_pool.get() is self and self._started
        if is_reentrant and len(self._ephemeral_workers) < self._concurrency:
            helper = asyncio.create_task(self._ephemeral_worker(future))
            self._ephemeral_workers.add(helper)
            helper.add_done_callback(self._ephemeral_workers.discard)

        if not self._queue.full():
            self._queue.put_nowait(item)
            return future

        put_task = asyncio.create_task(self._queue.put(item))
        self._pending_puts.add(put_task)
        try:
            await put_task
        except asyncio.CancelledError:
            if (
                put_task.done()
                and not put_task.cancelled()
                and put_task.exception() is None
            ):
                self._drain_queued_items()
            if inspect.iscoroutine(coro_func):
                coro_func.close()
            if self._aborting or self._stop_workers:
                if not future.done():
                    future.cancel()
                return future
            if self._shutting_down:
                if not future.done():
                    future.cancel()
                raise RuntimeError("Pool is shutting down")
            if not future.done():
                future.cancel()
            raise
        finally:
            self._pending_puts.discard(put_task)

        if self._aborting or self._stop_workers:
            self._drain_queued_items()
            if not future.done():
                future.cancel()
            return future

        return future

    def _drain_queued_items(self) -> None:
        while not self._queue.empty():
            try:
                item = self._queue.get_nowait()
            except asyncio.QueueEmpty:
                break
            try:
                if not item.future.done():
                    item.future.cancel()
                if inspect.iscoroutine(item.coro_func):
                    item.coro_func.close()
            finally:
                self._queue.task_done()

    async def _drain_all(self) -> None:
        while self._pending_puts:
            await asyncio.wait(
                list(self._pending_puts), return_when=asyncio.ALL_COMPLETED
            )
        await self._queue.join()

    def _all_worker_tasks(self) -> List[asyncio.Task]:
        return list(self._workers) + list(self._ephemeral_workers)

    def _abort_execution(self) -> None:
        self._aborting = True
        self._stop_workers = True

        for put_task in list(self._pending_puts):
            if not put_task.done():
                put_task.cancel()

        self._drain_queued_items()

        for exec_task in list(self._active_tasks):
            if not exec_task.done():
                exec_task.cancel()

        for worker in list(self._idle_workers):
            if not worker.done():
                worker.cancel()

    async def shutdown(
        self, drain: bool = True, timeout: Optional[float] = 5.0
    ) -> None:
        """Shuts down the worker pool.

        If drain=True, waits for all currently enqueued tasks to complete before
        stopping workers. If drain=False, cancels all queued and currently
        executing tasks immediately. Respects optional timeout in seconds.
        """
        if self._shutdown_done is None:
            self._shutdown_done = asyncio.Event()

        if self._shutting_down:
            if not drain and not self._aborting:
                self._abort_execution()
            if timeout is not None:
                try:
                    await asyncio.wait_for(self._shutdown_done.wait(), timeout=timeout)
                except asyncio.TimeoutError:
                    pass
            else:
                await self._shutdown_done.wait()
            return

        self._shutting_down = True
        loop = asyncio.get_running_loop()
        start_time = loop.time()

        try:
            if drain:
                if not self._started and (
                    not self._queue.empty() or self._pending_puts
                ):
                    self._started = True
                    self._workers = [
                        asyncio.create_task(
                            self._worker(i), name=f"AsyncWorkerPool-worker-{i}"
                        )
                        for i in range(self._concurrency)
                    ]

                try:
                    if timeout is not None:
                        await asyncio.wait_for(self._drain_all(), timeout=timeout)
                    else:
                        await self._drain_all()
                except asyncio.TimeoutError:
                    self._abort_execution()
                    all_workers = self._all_worker_tasks()
                    for worker in all_workers:
                        if not worker.done():
                            worker.cancel()
                    if all_workers:
                        await asyncio.gather(*all_workers, return_exceptions=True)
                    self._drain_queued_items()
                    for fut in list(self._tracked_futures):
                        if not fut.done():
                            fut.cancel()
                    return

                self._stop_workers = True
                all_workers = self._all_worker_tasks()
                for worker in list(self._idle_workers):
                    if not worker.done():
                        worker.cancel()
                for worker in all_workers:
                    if not worker.done():
                        worker.cancel()

                if all_workers:
                    remaining: Optional[float] = None
                    if timeout is not None:
                        remaining = max(0.0, timeout - (loop.time() - start_time))
                    try:
                        await asyncio.wait_for(
                            asyncio.gather(*all_workers, return_exceptions=True),
                            timeout=remaining,
                        )
                    except asyncio.TimeoutError:
                        for worker in all_workers:
                            if not worker.done():
                                worker.cancel()
                        await asyncio.gather(*all_workers, return_exceptions=True)
            else:
                self._abort_execution()

                all_workers = self._all_worker_tasks()
                if all_workers:
                    if timeout is not None:
                        try:
                            await asyncio.wait_for(
                                asyncio.gather(*all_workers, return_exceptions=True),
                                timeout=timeout,
                            )
                        except asyncio.TimeoutError:
                            for worker in self._all_worker_tasks():
                                if not worker.done():
                                    worker.cancel()
                            await asyncio.gather(
                                *self._all_worker_tasks(), return_exceptions=True
                            )
                    else:
                        await asyncio.gather(*all_workers, return_exceptions=True)

                self._drain_queued_items()
                for fut in list(self._tracked_futures):
                    if not fut.done():
                        fut.cancel()
        finally:
            self._shutdown_done.set()

    async def _execute_item(self, item: _WorkItem) -> None:
        try:
            if item.future.cancelled() or self._aborting:
                if not item.future.done():
                    item.future.cancel()
                if inspect.iscoroutine(item.coro_func):
                    item.coro_func.close()
                return

            token = _current_pool.set(self)
            try:
                if inspect.iscoroutine(item.coro_func):
                    coro = item.coro_func
                else:
                    coro = item.coro_func(*item.args, **item.kwargs)

                if not inspect.isawaitable(coro):
                    if not item.future.done():
                        item.future.set_result(coro)
                    return

                exec_task: asyncio.Task = asyncio.ensure_future(coro)
            except asyncio.CancelledError:
                if not item.future.done():
                    item.future.cancel()
                return
            except BaseException as exc:
                if not item.future.done():
                    item.future.set_exception(exc)
                    _ = item.future.exception()
                return
            finally:
                _current_pool.reset(token)

            self._active_tasks.add(exec_task)

            def _on_future_done(
                fut: asyncio.Future, task: asyncio.Task = exec_task
            ) -> None:
                if fut.cancelled() and not task.done():
                    task.cancel()

            item.future.add_done_callback(_on_future_done)
            try:
                result = await exec_task
            except asyncio.CancelledError:
                if not exec_task.done():
                    exec_task.cancel()
                if not item.future.done():
                    item.future.cancel()
            except BaseException as exc:
                if self._aborting:
                    if not item.future.done():
                        item.future.cancel()
                elif not item.future.done():
                    item.future.set_exception(exc)
                    _ = item.future.exception()
            else:
                if self._aborting:
                    if not item.future.done():
                        item.future.cancel()
                elif not item.future.done():
                    item.future.set_result(result)
            finally:
                self._active_tasks.discard(exec_task)
                item.future.remove_done_callback(_on_future_done)
        finally:
            self._queue.task_done()

    async def _ephemeral_worker(self, target_future: asyncio.Future) -> None:
        while not self._stop_workers and not target_future.done():
            try:
                item = self._queue.get_nowait()
            except asyncio.QueueEmpty:
                await asyncio.sleep(0)
                if self._queue.empty() and not self._pending_puts:
                    break
                continue
            await self._execute_item(item)

    async def _worker(self, worker_id: int) -> None:
        current_task = asyncio.current_task()
        assert current_task is not None

        while not self._stop_workers:
            self._idle_workers.add(current_task)
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break
            finally:
                self._idle_workers.discard(current_task)

            await self._execute_item(item)

    async def __aenter__(self) -> "AsyncWorkerPool":
        await self.start()
        return self

    async def __aexit__(self, exc_type: Any, exc_val: Any, exc_tb: Any) -> None:
        await self.shutdown(drain=True)
