from typing import Any


class QuorumCluster:
    def __init__(self, node_ids: list[str]) -> None:
        self.node_ids: list[str] = list(dict.fromkeys(node_ids))
        self.n: int = len(self.node_ids)
        self.quorum_size: int = (self.n // 2) + 1
        self.node_states: dict[str, dict[str, Any]] = {
            node_id: {} for node_id in self.node_ids
        }
        self.committed_state: dict[str, Any] = {}
        self.partitions: list[set[str]] = [set(self.node_ids)]

    def _get_partition_for_node(self, node_id: str) -> set[str] | None:
        for part in self.partitions:
            if node_id in part:
                return part
        return None

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        valid_nodes = set(self.node_ids)
        set_a = set(group_a) & valid_nodes
        set_b = (set(group_b) & valid_nodes) - set_a
        remaining = valid_nodes - set_a - set_b

        new_partitions: list[set[str]] = []
        if set_a:
            new_partitions.append(set_a)
        if set_b:
            new_partitions.append(set_b)
        for node_id in remaining:
            new_partitions.append({node_id})

        self.partitions = new_partitions

    def heal_partition(self) -> None:
        self.partitions = [set(self.node_ids)]
        for node_id in self.node_ids:
            self.node_states[node_id] = dict(self.committed_state)

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        part = self._get_partition_for_node(from_node)
        if part is None or len(part) < self.quorum_size:
            return False

        self.committed_state[key] = value
        for node_id in part:
            self.node_states[node_id][key] = value
        return True

    def read_value(self, from_node: str, key: str) -> Any:
        if from_node not in self.node_states:
            return None
        return self.node_states[from_node].get(key, None)
