import threading
from typing import Any, Dict, List


class ResilientConnectionPool:
    """A thread-safe, resilient database connection pool wrapper."""

    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0) -> None:
        if max_connections < 0:
            raise ValueError("max_connections must be non-negative")
        self.max_connections: int = max_connections
        self.ping_timeout: float = ping_timeout
        self._lock = threading.RLock()
        self._next_id: int = 1
        self._in_use: List[Dict[str, Any]] = []
        self.pool: List[Dict[str, Any]] = [
            self._create_connection() for _ in range(max_connections)
        ]

    @property
    def _pool(self) -> List[Dict[str, Any]]:
        return self.pool

    @_pool.setter
    def _pool(self, value: List[Dict[str, Any]]) -> None:
        self.pool = value

    @property
    def connections(self) -> List[Dict[str, Any]]:
        return self.pool

    @connections.setter
    def connections(self, value: List[Dict[str, Any]]) -> None:
        self.pool = value

    def _create_connection(self) -> Dict[str, Any]:
        conn: Dict[str, Any] = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return conn

    def acquire(self) -> dict:
        with self._lock:
            if not self.pool:
                raise RuntimeError("Pool exhausted")
            conn = self.pool.pop(0)
            self._in_use.append(conn)
            return conn

    def release(self, conn: dict) -> None:
        if not isinstance(conn, dict):
            return
        with self._lock:
            if conn in self._in_use:
                self._in_use.remove(conn)
            if conn not in self.pool and len(self.pool) < self.max_connections:
                self.pool.append(conn)

    def health_check_and_heal(self) -> int:
        with self._lock:
            healed_count = 0
            for idx, conn in enumerate(self.pool):
                if not conn.get("alive", False):
                    self.pool[idx] = self._create_connection()
                    healed_count += 1
            return healed_count

    def close_all(self) -> None:
        with self._lock:
            for conn in self.pool:
                conn["alive"] = False
            for conn in self._in_use:
                conn["alive"] = False
            self.pool.clear()
            self._in_use.clear()
