import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    """Prune unused imports and unreferenced top-level private functions from Python source code."""
    tree = ast.parse(source_code)

    # 1. Iteratively prune dead top-level private functions (starting with '_')
    #    until reaching a fixed point (handles chains of dead private helpers
    #    and ensures imports only used inside dead private functions are freed).
    while True:
        removed_any = False
        new_body: list[ast.stmt] = []

        for idx, stmt in enumerate(tree.body):
            if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith("_"):
                target_name = stmt.name
                referenced_elsewhere = False
                for other_idx, other_stmt in enumerate(tree.body):
                    if other_idx == idx:
                        continue
                    for node in ast.walk(other_stmt):
                        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load) and node.id == target_name:
                            referenced_elsewhere = True
                            break
                    if referenced_elsewhere:
                        break

                if not referenced_elsewhere:
                    removed_any = True
                    continue

            new_body.append(stmt)

        tree.body = new_body
        if not removed_any:
            break

    # 2. Collect all referenced identifiers in the remaining AST.
    used_names: set[str] = {
        node.id
        for node in ast.walk(tree)
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load)
    }

    # 3. Prune unused imports and filter partially used composite imports.
    class _ImportPruner(ast.NodeTransformer):
        def visit_Import(self, node: ast.Import) -> ast.Import | None:
            kept_aliases = [
                alias
                for alias in node.names
                if (alias.asname if alias.asname else alias.name.split(".")[0]) in used_names
            ]
            if not kept_aliases:
                return None
            node.names = kept_aliases
            return node

        def visit_ImportFrom(self, node: ast.ImportFrom) -> ast.ImportFrom | None:
            if node.module == "__future__":
                return node
            kept_aliases = [
                alias
                for alias in node.names
                if alias.name == "*" or (alias.asname or alias.name) in used_names
            ]
            if not kept_aliases:
                return None
            node.names = kept_aliases
            return node

    tree = _ImportPruner().visit(tree)
    ast.fix_missing_locations(tree)

    pruned_source = ast.unparse(tree)
    compile(pruned_source, "<ast_pruner>", "exec")
    return pruned_source
