import ntpath
import os
import posixpath
import shutil
import stat
import struct
import unicodedata
import zipfile


class _InvalidZipError(zipfile.BadZipFile, ValueError):
    """Exception raised when the archive is malformed, satisfying ValueError."""


def _has_nul_in_unicode_extra(extra: bytes) -> bool:
    offset = 0
    length = len(extra)
    while offset + 4 <= length:
        tp, ln = struct.unpack("<HH", extra[offset : offset + 4])
        end = offset + 4 + ln
        if end > length:
            break
        if tp == 0x7075 and ln >= 5:
            if b"\x00" in extra[offset + 9 : end]:
                return True
        offset = end
    return False


def _validate_and_normalize_path(
    raw_name: str, orig_name: str, is_dir: bool
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    for candidate in (raw_name, orig_name):
        if not isinstance(candidate, str) or not candidate:
            raise ValueError("Archive entry name must be a non-empty string")
        if "\x00" in candidate:
            raise ValueError("Archive entry contains a NUL byte")

    nfc_name = unicodedata.normalize("NFC", raw_name)
    nfc_orig = unicodedata.normalize("NFC", orig_name)

    for candidate in (raw_name, orig_name, nfc_name, nfc_orig):
        if (
            candidate.startswith(("/", "\\"))
            or posixpath.isabs(candidate)
            or ntpath.isabs(candidate)
            or ntpath.splitdrive(candidate)[0] != ""
        ):
            raise ValueError(f"Absolute entry path is not allowed: {candidate!r}")

        slash_normalized = candidate.replace("\\", "/")
        if ".." in slash_normalized.split("/"):
            raise ValueError(f"Path traversal entry is not allowed: {candidate!r}")

    raw_slash = raw_name.replace("\\", "/")
    nfc_slash = nfc_name.replace("\\", "/")
    if is_dir:
        raw_slash = raw_slash.rstrip("/")
        nfc_slash = nfc_slash.rstrip("/")

    raw_parts = tuple(p for p in raw_slash.split("/") if p and p != ".")
    nfc_parts = tuple(
        unicodedata.normalize("NFC", p)
        for p in nfc_slash.split("/")
        if p and p != "."
    )

    if len(raw_parts) != len(nfc_parts):
        raise ValueError("Inconsistent path components after Unicode normalization")

    for part in nfc_parts:
        if part in ("", ".", "..") or "/" in part or "\\" in part or "\x00" in part:
            raise ValueError(f"Invalid path component: {part!r}")

    if not nfc_parts and not is_dir:
        raise ValueError("File entry resolves to an empty path")

    return nfc_parts, raw_parts


def safe_extract_zip(
    archive_path: str,
    destination: str,
    max_files: int = 1000,
    max_uncompressed_bytes: int = 10000000,
    max_compression_ratio: float = 100.0,
) -> list[str]:
    if max_files < 0:
        raise ValueError("max_files must be non-negative")
    if max_uncompressed_bytes < 0:
        raise ValueError("max_uncompressed_bytes must be non-negative")
    if max_compression_ratio <= 0:
        raise ValueError("max_compression_ratio must be positive")

    archive_fs = os.fspath(archive_path)
    dest_fs = os.fspath(destination)
    if (isinstance(archive_fs, str) and "\x00" in archive_fs) or (
        isinstance(dest_fs, str) and "\x00" in dest_fs
    ):
        raise ValueError("Path argument contains a NUL byte")

    dest_abs = os.path.abspath(dest_fs)
    dest_real = os.path.realpath(dest_abs)
    if os.path.exists(dest_abs) and not os.path.isdir(dest_abs):
        raise ValueError("Destination exists and is not a directory")

    try:
        zf_ctx = zipfile.ZipFile(archive_fs, "r")
    except zipfile.BadZipFile as exc:
        raise _InvalidZipError("Invalid ZIP archive") from exc

    with zf_ctx as zf:
        infos = zf.infolist()

        seen_files: set[str] = set()
        seen_dirs: set[str] = set()
        implied_dirs: set[str] = set()
        dir_raw_prefixes: dict[str, tuple[str, ...]] = {}

        validated_dirs: list[tuple[str, ...]] = []
        validated_files: list[tuple[zipfile.ZipInfo, tuple[str, ...], str]] = []

        file_count = 0
        declared_total_bytes = 0

        for info in infos:
            orig_name = getattr(info, "orig_filename", info.filename)
            raw_name = info.filename

            if _has_nul_in_unicode_extra(getattr(info, "extra", b"")):
                raise ValueError("Archive entry extra field contains a NUL byte")

            unix_mode = (info.external_attr >> 16) & 0xFFFF
            if stat.S_ISLNK(unix_mode):
                raise ValueError(f"Unix symlink entry is not allowed: {raw_name!r}")
            if (
                stat.S_ISFIFO(unix_mode)
                or stat.S_ISCHR(unix_mode)
                or stat.S_ISBLK(unix_mode)
                or stat.S_ISSOCK(unix_mode)
            ):
                raise ValueError(f"Special Unix file entry is not allowed: {raw_name!r}")

            is_dir = (
                info.is_dir()
                or (isinstance(raw_name, str) and raw_name.endswith(("/", "\\")))
                or (isinstance(orig_name, str) and orig_name.endswith(("/", "\\")))
                or stat.S_ISDIR(unix_mode)
            )

            nfc_parts, raw_parts = _validate_and_normalize_path(
                raw_name, orig_name, is_dir
            )
            norm_path = "/".join(nfc_parts)

            if info.file_size < 0 or info.compress_size < 0:
                raise ValueError("Negative size in archive entry header")

            if is_dir:
                if info.file_size != 0:
                    raise ValueError("Directory entry must have zero size")
                if norm_path in seen_dirs or norm_path in seen_files:
                    raise ValueError(
                        f"Duplicate or colliding directory entry: {norm_path!r}"
                    )
                seen_dirs.add(norm_path)
                for idx in range(1, len(nfc_parts) + 1):
                    prefix = "/".join(nfc_parts[:idx])
                    raw_prefix = raw_parts[:idx]
                    if idx < len(nfc_parts):
                        implied_dirs.add(prefix)
                    prev_raw = dir_raw_prefixes.get(prefix)
                    if prev_raw is not None and prev_raw != raw_prefix:
                        raise ValueError(f"NFC collision on directory path: {prefix!r}")
                    dir_raw_prefixes[prefix] = raw_prefix
                if nfc_parts:
                    validated_dirs.append(nfc_parts)
            else:
                file_count += 1
                if file_count > max_files:
                    raise ValueError("Archive exceeds max_files limit")

                if info.file_size > 0:
                    if info.compress_size <= 0:
                        raise ValueError("Non-empty entry has zero compressed size")
                    if (info.file_size / info.compress_size) > max_compression_ratio:
                        raise ValueError("Entry exceeds max_compression_ratio limit")

                declared_total_bytes += info.file_size
                if declared_total_bytes > max_uncompressed_bytes:
                    raise ValueError("Archive exceeds max_uncompressed_bytes limit")

                if (
                    norm_path in seen_files
                    or norm_path in seen_dirs
                    or norm_path in implied_dirs
                ):
                    raise ValueError(
                        f"Duplicate or colliding file entry: {norm_path!r}"
                    )
                seen_files.add(norm_path)

                for idx in range(1, len(nfc_parts)):
                    prefix = "/".join(nfc_parts[:idx])
                    raw_prefix = raw_parts[:idx]
                    implied_dirs.add(prefix)
                    prev_raw = dir_raw_prefixes.get(prefix)
                    if prev_raw is not None and prev_raw != raw_prefix:
                        raise ValueError(f"NFC collision on directory path: {prefix!r}")
                    dir_raw_prefixes[prefix] = raw_prefix

                validated_files.append((info, nfc_parts, norm_path))

        if seen_files & (seen_dirs | implied_dirs):
            raise ValueError("Entry name collides between file and directory")

        for parts in validated_dirs + [item[1] for item in validated_files]:
            target_abs = os.path.abspath(os.path.join(dest_abs, *parts))
            target_real = os.path.realpath(target_abs)
            if (
                os.path.commonpath([dest_real, target_real]) != dest_real
                or target_real == dest_real
            ):
                raise ValueError("Resolved entry path escapes destination")

            cur = dest_abs
            for idx, part in enumerate(parts):
                cur = os.path.join(cur, part)
                if os.path.islink(cur):
                    raise ValueError("Destination path contains a symlink component")
                if idx < len(parts) - 1:
                    if os.path.exists(cur) and not os.path.isdir(cur):
                        raise ValueError(
                            "Destination ancestor exists and is not a directory"
                        )

        for parts in validated_dirs:
            target = os.path.join(dest_abs, *parts)
            if os.path.exists(target) and not os.path.isdir(target):
                raise ValueError("Destination path for directory exists as a file")

        for _, parts, _ in validated_files:
            target = os.path.join(dest_abs, *parts)
            if os.path.exists(target) and os.path.isdir(target):
                raise ValueError("Destination path for file exists as a directory")

        actual_total_bytes = 0
        chunk_size = 65536
        for info, _, _ in validated_files:
            actual_file_bytes = 0
            try:
                with zf.open(info, "r") as src:
                    while True:
                        chunk = src.read(chunk_size)
                        if not chunk:
                            break
                        actual_file_bytes += len(chunk)
                        actual_total_bytes += len(chunk)
                        if actual_total_bytes > max_uncompressed_bytes:
                            raise ValueError(
                                "Archive exceeds max_uncompressed_bytes limit"
                            )
                        if actual_file_bytes > 0:
                            if (
                                info.compress_size <= 0
                                or (actual_file_bytes / info.compress_size)
                                > max_compression_ratio
                            ):
                                raise ValueError(
                                    "Entry exceeds max_compression_ratio limit"
                                )
            except zipfile.BadZipFile as exc:
                raise _InvalidZipError("Corrupted ZIP stream") from exc

            if actual_file_bytes != info.file_size:
                raise ValueError("Entry uncompressed size does not match header")

        os.makedirs(dest_abs, exist_ok=True)

        for parts in validated_dirs:
            os.makedirs(os.path.join(dest_abs, *parts), exist_ok=True)

        extracted_paths: list[str] = []
        for info, parts, norm_path in validated_files:
            target_path = os.path.join(dest_abs, *parts)
            parent_dir = os.path.dirname(target_path)
            if parent_dir:
                os.makedirs(parent_dir, exist_ok=True)
            with zf.open(info, "r") as src, open(target_path, "wb") as dst:
                shutil.copyfileobj(src, dst, length=chunk_size)
            extracted_paths.append(norm_path)

        return sorted(extracted_paths)
