from fnmatch import fnmatchcase
from typing import Any

_REQUEST_KEYS = frozenset(
    {
        "subject_id",
        "tenant_id",
        "resource_tenant_id",
        "roles",
        "action",
        "resource",
        "context",
    }
)
_REQUIRED_POLICY_KEYS = frozenset(
    {"effect", "tenant", "roles", "actions", "resources"}
)
_ALLOWED_POLICY_KEYS = _REQUIRED_POLICY_KEYS | {"conditions"}


def _is_non_empty_str(value: Any) -> bool:
    return isinstance(value, str) and len(value.strip()) > 0


def _is_non_empty_str_list(value: Any) -> bool:
    return (
        isinstance(value, list)
        and len(value) > 0
        and all(_is_non_empty_str(item) for item in value)
    )


def _is_scalar(value: Any) -> bool:
    return isinstance(value, (str, int, float, bool))


def _scalar_equals(a: Any, b: Any) -> bool:
    if isinstance(a, bool) != isinstance(b, bool):
        return False
    return _is_scalar(a) and _is_scalar(b) and a == b


def _is_valid_request(request: Any) -> bool:
    if not isinstance(request, dict):
        return False
    if set(request.keys()) != _REQUEST_KEYS:
        return False
    if not (
        _is_non_empty_str(request["subject_id"])
        and _is_non_empty_str(request["tenant_id"])
        and _is_non_empty_str(request["resource_tenant_id"])
        and _is_non_empty_str_list(request["roles"])
        and _is_non_empty_str(request["action"])
        and _is_non_empty_str(request["resource"])
        and isinstance(request["context"], dict)
    ):
        return False
    return all(_is_non_empty_str(k) for k in request["context"])


def _is_valid_policy(policy: Any) -> bool:
    if not isinstance(policy, dict):
        return False
    keys = set(policy.keys())
    if not _REQUIRED_POLICY_KEYS.issubset(keys) or not keys.issubset(
        _ALLOWED_POLICY_KEYS
    ):
        return False
    if not isinstance(policy["effect"], str) or policy["effect"] not in (
        "allow",
        "deny",
    ):
        return False
    if not _is_non_empty_str(policy["tenant"]):
        return False
    if not (
        _is_non_empty_str_list(policy["roles"])
        and _is_non_empty_str_list(policy["actions"])
        and _is_non_empty_str_list(policy["resources"])
    ):
        return False
    if "conditions" in policy:
        conditions = policy["conditions"]
        if not isinstance(conditions, dict):
            return False
        for key, val in conditions.items():
            if not _is_non_empty_str(key):
                return False
            if isinstance(val, list):
                if len(val) == 0 or not all(_is_scalar(item) for item in val):
                    return False
            elif not _is_scalar(val):
                return False
    return True


def _matches_conditions(context: dict, conditions: dict) -> bool:
    for key, expected in conditions.items():
        if key not in context:
            return False
        actual = context[key]
        if isinstance(expected, list):
            if not any(_scalar_equals(actual, item) for item in expected):
                return False
        else:
            if not _scalar_equals(actual, expected):
                return False
    return True


def _policy_matches(request: dict, policy: dict) -> bool:
    if policy["tenant"] != "*" and policy["tenant"] != request["tenant_id"]:
        return False

    policy_roles = policy["roles"]
    if "*" not in policy_roles and not any(
        role in policy_roles for role in request["roles"]
    ):
        return False

    if not any(
        fnmatchcase(request["action"], pattern) for pattern in policy["actions"]
    ):
        return False

    if not any(
        fnmatchcase(request["resource"], pattern)
        for pattern in policy["resources"]
    ):
        return False

    conditions = policy.get("conditions")
    if conditions and not _matches_conditions(request["context"], conditions):
        return False

    return True


def authorize(request: dict, policies: list[dict]) -> bool:
    if not _is_valid_request(request):
        return False

    if request["tenant_id"] != request["resource_tenant_id"]:
        return False

    if not isinstance(policies, list) or not all(
        _is_valid_policy(policy) for policy in policies
    ):
        return False

    allowed = False
    for policy in policies:
        if _policy_matches(request, policy):
            if policy["effect"] == "deny":
                return False
            allowed = True

    return allowed
