from dataclasses import dataclass
from decimal import Decimal
import re
from typing import Dict, Optional

_AMOUNT_PATTERN = re.compile(r"\A[0-9]+(?:\.[0-9]{1,2})?\Z")
_TWO_PLACES = Decimal("0.01")
_ZERO = Decimal("0.00")
_REQUIRED_KEYS = frozenset({"event_id", "payment_id", "sequence", "type", "amount"})
_VALID_TYPES = frozenset({"authorized", "captured", "refunded", "reversed"})


@dataclass(frozen=True)
class _EventRecord:
    event_id: str
    payment_id: str
    sequence: int
    type: str
    amount: Decimal


@dataclass(frozen=True)
class _PaymentState:
    authorized: Decimal = _ZERO
    captured: Decimal = _ZERO
    refunded: Decimal = _ZERO
    reversed: Decimal = _ZERO
    next_sequence: int = 1


class PaymentLedger:
    def __init__(self) -> None:
        self._payments: Dict[str, _PaymentState] = {}
        self._buffered: Dict[str, Dict[int, _EventRecord]] = {}
        self._events_by_id: Dict[str, _EventRecord] = {}

    @staticmethod
    def _validate_event(event: dict) -> _EventRecord:
        if not isinstance(event, dict):
            raise ValueError("Event must be a dictionary.")
        if set(event.keys()) != _REQUIRED_KEYS:
            raise ValueError("Event must contain exact required fields.")

        event_id = event["event_id"]
        payment_id = event["payment_id"]
        sequence = event["sequence"]
        event_type = event["type"]
        amount_raw = event["amount"]

        if not isinstance(event_id, str) or not event_id.strip():
            raise ValueError("event_id must be a non-empty string.")
        if not isinstance(payment_id, str) or not payment_id.strip():
            raise ValueError("payment_id must be a non-empty string.")
        if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:
            raise ValueError("sequence must be a positive integer.")
        if not isinstance(event_type, str) or event_type not in _VALID_TYPES:
            raise ValueError("Unsupported event type.")
        if not isinstance(amount_raw, str) or not _AMOUNT_PATTERN.match(amount_raw):
            raise ValueError(
                "amount must be a positive decimal string with at most two fractional digits."
            )

        amount = Decimal(amount_raw).quantize(_TWO_PLACES)
        if amount <= _ZERO:
            raise ValueError("amount must be greater than zero.")

        return _EventRecord(
            event_id=event_id,
            payment_id=payment_id,
            sequence=sequence,
            type=event_type,
            amount=amount,
        )

    @staticmethod
    def _apply_single(state: _PaymentState, record: _EventRecord) -> _PaymentState:
        if record.sequence != state.next_sequence:
            raise ValueError("Non-consecutive sequence.")

        if record.sequence == 1:
            if record.type != "authorized":
                raise ValueError("Sequence 1 must authorize.")
            return _PaymentState(
                authorized=record.amount,
                captured=_ZERO,
                refunded=_ZERO,
                reversed=_ZERO,
                next_sequence=2,
            )

        if record.type == "authorized":
            raise ValueError("Authorization is only permitted at sequence 1.")

        if record.type == "captured":
            new_captured = state.captured + record.amount
            if new_captured > state.authorized:
                raise ValueError("Capture cannot exceed authorization.")
            return _PaymentState(
                authorized=state.authorized,
                captured=new_captured,
                refunded=state.refunded,
                reversed=state.reversed,
                next_sequence=state.next_sequence + 1,
            )

        remaining_settled = state.captured - state.refunded - state.reversed
        if record.amount > remaining_settled:
            raise ValueError("Amount exceeds remaining settled balance.")

        if record.type == "refunded":
            return _PaymentState(
                authorized=state.authorized,
                captured=state.captured,
                refunded=state.refunded + record.amount,
                reversed=state.reversed,
                next_sequence=state.next_sequence + 1,
            )

        if record.type == "reversed":
            return _PaymentState(
                authorized=state.authorized,
                captured=state.captured,
                refunded=state.refunded,
                reversed=state.reversed + record.amount,
                next_sequence=state.next_sequence + 1,
            )

        raise ValueError("Invalid event type.")

    def apply(self, event: dict) -> str:
        record = self._validate_event(event)

        existing = self._events_by_id.get(record.event_id)
        if existing is not None:
            if existing == record:
                return "duplicate"
            raise ValueError("Event ID reused with different content.")

        current_state = self._payments.get(record.payment_id, _PaymentState())
        payment_buffer = self._buffered.get(record.payment_id, {})

        if record.sequence < current_state.next_sequence or record.sequence in payment_buffer:
            raise ValueError("Sequence number already used with different content.")

        if record.sequence > current_state.next_sequence:
            if record.payment_id not in self._buffered:
                self._buffered[record.payment_id] = {}
            self._buffered[record.payment_id][record.sequence] = record
            self._events_by_id[record.event_id] = record
            return "buffered"

        chain = [record]
        seq = record.sequence + 1
        while seq in payment_buffer:
            chain.append(payment_buffer[seq])
            seq += 1

        candidate_state = current_state
        for item in chain:
            candidate_state = self._apply_single(candidate_state, item)

        self._payments[record.payment_id] = candidate_state
        self._events_by_id[record.event_id] = record
        if len(chain) > 1:
            buf = self._buffered[record.payment_id]
            for item in chain[1:]:
                del buf[item.sequence]
            if not buf:
                del self._buffered[record.payment_id]

        return "applied"

    @staticmethod
    def _format_state(state: _PaymentState) -> dict:
        available_to_capture = state.authorized - state.captured
        merchant_balance = state.captured - state.refunded - state.reversed
        return {
            "authorized": str(state.authorized.quantize(_TWO_PLACES)),
            "captured": str(state.captured.quantize(_TWO_PLACES)),
            "refunded": str(state.refunded.quantize(_TWO_PLACES)),
            "reversed": str(state.reversed.quantize(_TWO_PLACES)),
            "available_to_capture": str(available_to_capture.quantize(_TWO_PLACES)),
            "merchant_balance": str(merchant_balance.quantize(_TWO_PLACES)),
            "next_sequence": state.next_sequence,
        }

    def state(self, payment_id: str) -> Optional[dict]:
        if not isinstance(payment_id, str):
            return None
        payment_state = self._payments.get(payment_id)
        if payment_state is None:
            return None
        return self._format_state(payment_state)

    def snapshot(self) -> dict:
        return {
            payment_id: self._format_state(self._payments[payment_id])
            for payment_id in sorted(self._payments.keys())
        }
