from typing import Callable


class RetryableError(Exception):
    """Raised when a saga step fails transiently and can be retried."""


class FatalError(Exception):
    """Raised when a saga step fails permanently and requires compensation."""


class CrashError(Exception):
    """Raised when execution crashes and must halt immediately without extra work."""


class SagaOrchestrator:
    def __init__(
        self,
        executor: Callable[[str], object],
        compensator: Callable[[str], object],
        max_retries: int = 2,
        journal: dict | None = None,
    ) -> None:
        if not callable(executor):
            raise ValueError("executor must be callable")
        if not callable(compensator):
            raise ValueError("compensator must be callable")
        if isinstance(max_retries, bool) or not isinstance(max_retries, int) or max_retries < 0:
            raise ValueError("max_retries must be a non-negative integer")
        if journal is not None and not isinstance(journal, dict):
            raise ValueError("journal must be a dict or None")

        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        self.journal: dict = journal if journal is not None else {}

    def _validate_and_prepare(self, saga_id: str, steps: list[str]) -> dict:
        if not isinstance(saga_id, str) or not saga_id.strip():
            raise ValueError("saga_id must be a non-empty string")
        if not isinstance(steps, (list, tuple)) or len(steps) == 0:
            raise ValueError("steps must be a non-empty list of strings")
        if any(not isinstance(step, str) or not step.strip() for step in steps):
            raise ValueError("All steps must be non-empty strings")
        if len(set(steps)) != len(steps):
            raise ValueError("Steps must be unique")

        normalized_steps = list(steps)
        if saga_id in self.journal:
            entry = self.journal[saga_id]
            if not isinstance(entry, dict) or entry.get("steps") != normalized_steps:
                raise ValueError(f"Step plan changed for existing saga '{saga_id}'")
            return entry

        entry = {
            "steps": normalized_steps,
            "status": "running",
            "completed_steps": [],
            "compensated_steps": [],
        }
        self.journal[saga_id] = entry
        return entry

    def _invoke_with_retries(self, callback: Callable[[str], object], step: str) -> None:
        attempts = 0
        while True:
            try:
                callback(step)
                return
            except CrashError:
                raise
            except RetryableError as exc:
                if attempts >= self.max_retries:
                    raise FatalError(f"Retries exhausted for step '{step}'") from exc
                attempts += 1
            except FatalError:
                raise
            except Exception as exc:
                raise FatalError(f"Undeclared callback error for step '{step}'") from exc

    def _compensate(self, entry: dict) -> str:
        entry["status"] = "compensating"
        completed_steps: list[str] = entry["completed_steps"]
        compensated_steps: list[str] = entry["compensated_steps"]

        for step in reversed(list(completed_steps)):
            if step in compensated_steps:
                continue
            self._invoke_with_retries(self.compensator, step)
            compensated_steps.append(step)

        entry["status"] = "compensated"
        return "compensated"

    def _execute(self, entry: dict) -> str:
        status = entry.get("status")
        if status == "completed":
            return "completed"
        if status == "compensated":
            return "compensated"
        if status == "compensating":
            return self._compensate(entry)

        completed_steps: list[str] = entry["completed_steps"]
        for step in entry["steps"]:
            if step in completed_steps:
                continue
            try:
                self._invoke_with_retries(self.executor, step)
            except CrashError:
                raise
            except Exception:
                return self._compensate(entry)
            completed_steps.append(step)

        entry["status"] = "completed"
        return "completed"

    def run(self, saga_id: str, steps: list[str]) -> str:
        entry = self._validate_and_prepare(saga_id, steps)
        return self._execute(entry)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        entry = self._validate_and_prepare(saga_id, steps)
        return self._execute(entry)
