import re

_VALID_LEADING_KEYWORDS = {
    "SELECT", "WHERE", "VALUES", "SET", "AND", "OR", "NOT", "IN", "LIKE",
    "ILIKE", "IS", "AS", "FROM", "JOIN", "INNER", "LEFT", "RIGHT", "FULL",
    "CROSS", "ON", "HAVING", "GROUP", "ORDER", "WHEN", "THEN", "ELSE",
    "CASE", "END", "BY", "OVER", "PARTITION", "LIMIT", "OFFSET", "FETCH",
    "INTO", "DEFAULT", "ESCAPE", "SIMILAR", "REGEXP", "RLIKE", "MATCH",
    "AGAINST", "WITH", "RECURSIVE", "INSERT", "UPDATE", "DELETE", "REPLACE",
    "MERGE", "UPSERT", "EXPLAIN", "SHOW", "DESCRIBE", "DESC", "PRAGMA",
    "CALL", "EXEC", "EXECUTE", "RETURN", "PRINT", "CREATE", "ALTER", "DROP",
    "TRUNCATE", "BEGIN", "START", "COMMIT", "ROLLBACK", "SAVEPOINT", "GRANT",
    "REVOKE", "USE", "DECLARE", "OPEN", "CLOSE", "DEALLOCATE", "TABLE",
    "DISTINCT", "ALL", "ANY", "SOME", "EXISTS", "BETWEEN", "CAST", "EXTRACT",
}

_CLAUSE_BOUNDARIES = {
    "SELECT", "FROM", "WHERE", "AND", "OR", "ON", "HAVING", "GROUP", "ORDER",
    "LIMIT", "OFFSET", "WHEN", "THEN", "ELSE", "SET", "VALUES", "INTO",
    "JOIN", "INNER", "LEFT", "RIGHT", "FULL", "CROSS", "UNION", "INTERSECT",
    "EXCEPT", "OVER", "PARTITION", "BY", "RETURNING", "CASE", "END",
}

_COMPARISON_OPS = {
    "=", "!=", "<>", "<", ">", "<=", ">=", "<=>",
    "LIKE", "ILIKE", "RLIKE", "REGEXP", "IS",
}


def _tokenize_sql(sql_text: str) -> tuple[list[tuple[str, str, str]], list[tuple[str, str]]]:
    tokens: list[tuple[str, str, str]] = []
    issues: list[tuple[str, str]] = []
    n = len(sql_text)
    i = 0

    while i < n:
        ch = sql_text[i]

        if ch.isspace():
            i += 1
            continue

        # Block comments: /* ... */ and MySQL conditional comments /*! ... */
        if ch == "/" and i + 1 < n and sql_text[i + 1] == "*":
            prev_non_space = i > 0 and not sql_text[i - 1].isspace()
            is_conditional = i + 2 < n and sql_text[i + 2] == "!"
            end_idx = sql_text.find("*/", i + 2)
            if end_idx == -1:
                issues.append(("OBFUSCATION", "Obfuscation / inline comment evasion: unclosed block comment"))
                break
            body = sql_text[i + 2 : end_idx]
            after_idx = end_idx + 2
            next_non_space = after_idx < n and not sql_text[after_idx].isspace()
            if is_conditional:
                issues.append(("OBFUSCATION", "Obfuscation / inline comment evasion: MySQL conditional comment"))
            elif body.strip() == "" or prev_non_space or next_non_space:
                issues.append(("OBFUSCATION", "Obfuscation / inline comment evasion: inline comment token splitting"))
            else:
                issues.append(("OBFUSCATION", "Obfuscation / inline comment evasion: block comment detected"))
            i = after_idx
            continue

        # Standard SQL line comment: --
        if ch == "-" and i + 1 < n and sql_text[i + 1] == "-":
            end_idx = sql_text.find("\n", i + 2)
            if end_idx == -1:
                comment_val = sql_text[i:]
                i = n
            else:
                comment_val = sql_text[i:end_idx]
                i = end_idx + 1
            tokens.append(("LINE_COMMENT", comment_val, comment_val.upper()))
            issues.append(("COMMENT", "Boolean/Tautology or comment truncation injection: line comment (--)"))
            continue

        # PostgreSQL JSON path extraction (#>, #>>) vs MySQL hash line comment (#)
        if ch == "#":
            if i + 1 < n and sql_text[i + 1] == ">":
                if i + 2 < n and sql_text[i + 2] == ">":
                    tokens.append(("OP", "#>>", "#>>"))
                    i += 3
                else:
                    tokens.append(("OP", "#>", "#>"))
                    i += 2
                continue
            end_idx = sql_text.find("\n", i + 1)
            if end_idx == -1:
                comment_val = sql_text[i:]
                i = n
            else:
                comment_val = sql_text[i:end_idx]
                i = end_idx + 1
            tokens.append(("LINE_COMMENT", comment_val, comment_val.upper()))
            issues.append(("COMMENT", "Boolean/Tautology or comment truncation injection: hash comment (#)"))
            continue

        # Single-quoted or double-quoted strings / identifiers
        if ch in ("'", '"'):
            quote_char = ch
            if i > 0 and (sql_text[i - 1].isalnum() or sql_text[i - 1] == "_"):
                if not (
                    quote_char == "'"
                    and tokens
                    and tokens[-1][0] == "WORD"
                    and tokens[-1][2] in {"N", "E", "B", "X", "U"}
                    and (i - len(tokens[-1][1]) == 0 or not sql_text[i - len(tokens[-1][1]) - 1].isalnum())
                ):
                    issues.append(("BREAKOUT", "Boolean/Tautology injection: quote breakout adjacent to identifier"))

            # Empty string literal ('' or "") not followed by an immediate third quote
            if i + 1 < n and sql_text[i + 1] == quote_char and (i + 2 >= n or sql_text[i + 2] != quote_char):
                lit = sql_text[i : i + 2]
                tokens.append(("STRING", lit, lit.upper()))
                if i + 2 < n and (sql_text[i + 2].isalnum() or sql_text[i + 2] == "_"):
                    issues.append(("BREAKOUT", "Boolean/Tautology injection: token immediately following string literal"))
                i += 2
                continue

            j = i + 1
            closed = False
            while j < n:
                c = sql_text[j]
                if c == "\\":
                    j += 2
                    continue
                if c == quote_char:
                    if j + 1 < n and sql_text[j + 1] == quote_char:
                        j += 2
                        continue
                    closed = True
                    lit = sql_text[i : j + 1]
                    if quote_char == '"' and re.match(r'^"[a-zA-Z_][a-zA-Z0-9_]*"$', lit):
                        tokens.append(("IDENT_DQ", lit, lit[1:-1].upper()))
                    else:
                        tokens.append(("STRING", lit, lit.upper()))
                    if j + 1 < n and (sql_text[j + 1].isalnum() or sql_text[j + 1] == "_"):
                        issues.append(("BREAKOUT", "Boolean/Tautology injection: token immediately following closing quote"))
                    i = j + 1
                    break
                j += 1

            if not closed:
                lit = sql_text[i:]
                tokens.append(("STRING", lit, lit.upper()))
                issues.append(("UNCLOSED_QUOTE", "Boolean/Tautology injection: unclosed string quote"))
                i = n
            continue

        # Backtick-quoted identifiers
        if ch == "`":
            j = sql_text.find("`", i + 1)
            if j == -1:
                issues.append(("UNCLOSED_QUOTE", "Boolean/Tautology injection: unclosed backtick"))
                i = n
            else:
                lit = sql_text[i : j + 1]
                tokens.append(("WORD", lit, lit[1:-1].upper()))
                i = j + 1
            continue

        if ch == ";":
            tokens.append(("SEMICOLON", ";", ";"))
            i += 1
            continue

        if ch in ("(", ")", ",", ".", "[", "]"):
            tokens.append(("PUNCT", ch, ch))
            i += 1
            continue

        if ch in ("-", "=", "!", "<", ">", "+", "*", "/", "%", "|", "&", "^", "~", ":", "@", "?"):
            if sql_text[i : i + 3] in ("->>", "<=>"):
                op = sql_text[i : i + 3]
                tokens.append(("OP", op, op))
                i += 3
                continue
            if sql_text[i : i + 2] in ("->", "!=", "<>", "<=", ">=", "||", "&&", "::", "@>", "<@", "?|", "?&", "+=", "-="):
                op = sql_text[i : i + 2]
                tokens.append(("OP", op, op))
                i += 2
                continue
            tokens.append(("OP", ch, ch))
            i += 1
            continue

        if ch.isdigit():
            m = re.match(r"^(?:0[xX][0-9a-fA-F]+|\d+(?:\.\d+)?(?:[eE][+-]?\d+)?)", sql_text[i:])
            if m:
                num_str = m.group(0)
                tokens.append(("NUMBER", num_str, num_str.upper()))
                i += len(num_str)
                continue

        if ch.isalpha() or ch in ("_", "$"):
            m = re.match(r"^[a-zA-Z_$][a-zA-Z0-9_$]*", sql_text[i:])
            if m:
                w = m.group(0)
                tokens.append(("WORD", w, w.upper()))
                i += len(w)
                continue

        tokens.append(("OTHER", ch, ch.upper()))
        i += 1

    return tokens, issues


def _expr_has_identifier(expr_tokens: list[tuple[str, str, str]]) -> bool:
    for t_type, _, t_upper in expr_tokens:
        if t_type == "IDENT_DQ":
            return True
        if t_type == "WORD" and t_upper not in {"TRUE", "FALSE", "NULL", "NOT", "UNKNOWN"}:
            return True
    return False


def _normalize_expr(expr_tokens: list[tuple[str, str, str]]) -> list[tuple[str, str]]:
    return [
        (t_type, t_upper)
        for t_type, _, t_upper in expr_tokens
        if not (t_type == "PUNCT" and t_upper in {"(", ")"})
    ]


def _analyze_token_stream(
    tokens: list[tuple[str, str, str]],
    issues: list[tuple[str, str]],
    has_leading_breakout: bool = False,
) -> tuple[bool, str]:
    # 1. Obfuscation / inline comment evasion
    for cat, msg in issues:
        if cat == "OBFUSCATION":
            return False, msg

    code_tokens = [t for t in tokens if t[0] != "LINE_COMMENT"]
    m = len(code_tokens)

    for idx, (t_type, _, t_upper) in enumerate(code_tokens):
        if t_type == "WORD" and t_upper in {"CHAR", "CHR"} and idx + 1 < m and code_tokens[idx + 1][2] == "(":
            j = idx + 2
            num_count = 0
            while j < m and code_tokens[j][2] != ")":
                if code_tokens[j][0] == "NUMBER":
                    num_count += 1
                j += 1
            if num_count >= 2:
                return False, "Obfuscation / character encoding evasion detected"
            if (
                j + 1 < m
                and code_tokens[j + 1][2] in {"||", "+"}
                and j + 2 < m
                and code_tokens[j + 2][2] in {"CHAR", "CHR"}
            ):
                return False, "Obfuscation / character encoding concatenation detected"

    # 2. Time-based blind execution
    for idx, (t_type, _, t_upper) in enumerate(code_tokens):
        if t_type == "WORD":
            if t_upper in {"PG_SLEEP", "PG_SLEEP_FOR", "PG_SLEEP_UNTIL"}:
                return False, f"Time-based blind execution detected: {t_upper}"
            if t_upper in {"SLEEP", "BENCHMARK"} and idx + 1 < m and code_tokens[idx + 1][2] == "(":
                return False, f"Time-based blind execution detected: {t_upper}()"
            if t_upper == "WAITFOR" and idx + 1 < m and code_tokens[idx + 1][2] in {"DELAY", "TIME"}:
                return False, f"Time-based blind execution detected: WAITFOR {code_tokens[idx + 1][2]}"
            if t_upper in {"DBMS_PIPE", "RECEIVE_MESSAGE"}:
                return False, "Time-based blind execution detected: DBMS_PIPE.RECEIVE_MESSAGE"
            if (
                t_upper == "DBMS_LOCK"
                and idx + 2 < m
                and code_tokens[idx + 1][2] == "."
                and code_tokens[idx + 2][2] == "SLEEP"
            ):
                return False, "Time-based blind execution detected: DBMS_LOCK.SLEEP"

    # 3. UNION-based data exfiltration
    for idx, (t_type, _, t_upper) in enumerate(code_tokens):
        if t_type == "WORD" and t_upper == "UNION":
            j = idx + 1
            while j < m and (
                (code_tokens[j][0] == "WORD" and code_tokens[j][2] in {"ALL", "DISTINCT"})
                or (code_tokens[j][0] == "PUNCT" and code_tokens[j][2] == "(")
            ):
                j += 1
            if j < m and code_tokens[j][0] == "WORD" and code_tokens[j][2] in {"SELECT", "VALUES", "TABLE"}:
                return False, "UNION-based data exfiltration detected"
            if j == m:
                return False, "UNION-based data exfiltration detected"

    # 4. Stacked query execution
    for idx, (t_type, _, t_upper) in enumerate(tokens):
        if t_type == "SEMICOLON":
            if idx == 0:
                return False, "Stacked query execution detected: leading semicolon"
            remaining = [t for t in tokens[idx + 1 :] if t[0] != "SEMICOLON"]
            if remaining:
                return False, "Stacked query execution detected: multiple statements after semicolon"
        if t_type == "WORD" and t_upper in {"XP_CMDSHELL", "SP_OACREATE", "SP_CONFIGURE", "XP_REGREAD"}:
            return False, f"Stacked / command execution detected: {t_upper}"

    # 5. Boolean / Tautology injection
    first_non_paren = 0
    while (
        first_non_paren < m
        and code_tokens[first_non_paren][0] == "PUNCT"
        and code_tokens[first_non_paren][2] in {"(", ")"}
    ):
        first_non_paren += 1
    if (
        first_non_paren < m
        and code_tokens[first_non_paren][0] == "WORD"
        and code_tokens[first_non_paren][2] in {"OR", "AND"}
    ):
        return False, f"Boolean/Tautology injection detected: leading {code_tokens[first_non_paren][2]} operator"

    for idx, (t_type, _, t_upper) in enumerate(code_tokens):
        is_comp = (t_type == "OP" and t_upper in _COMPARISON_OPS) or (
            t_type == "WORD" and t_upper in _COMPARISON_OPS
        )
        if is_comp:
            lhs: list[tuple[str, str, str]] = []
            k = idx - 1
            paren_depth = 0
            while k >= 0:
                kt_type, _, kt_upper = code_tokens[k]
                if kt_type == "PUNCT":
                    if kt_upper == ")":
                        paren_depth += 1
                    elif kt_upper == "(":
                        if paren_depth == 0:
                            break
                        paren_depth -= 1
                    elif kt_upper == "," and paren_depth == 0:
                        break
                elif paren_depth == 0:
                    if kt_type == "SEMICOLON":
                        break
                    if kt_type == "WORD" and kt_upper in _CLAUSE_BOUNDARIES:
                        break
                    if kt_type == "OP" and kt_upper in _COMPARISON_OPS:
                        break
                lhs.append(code_tokens[k])
                k -= 1
            lhs.reverse()

            rhs: list[tuple[str, str, str]] = []
            k = idx + 1
            paren_depth = 0
            while k < m:
                kt_type, _, kt_upper = code_tokens[k]
                if kt_type == "PUNCT":
                    if kt_upper == "(":
                        paren_depth += 1
                    elif kt_upper == ")":
                        if paren_depth == 0:
                            break
                        paren_depth -= 1
                    elif kt_upper == "," and paren_depth == 0:
                        break
                elif paren_depth == 0:
                    if kt_type == "SEMICOLON":
                        break
                    if kt_type == "WORD" and kt_upper in _CLAUSE_BOUNDARIES:
                        break
                    if kt_type == "OP" and kt_upper in _COMPARISON_OPS:
                        break
                rhs.append(code_tokens[k])
                k += 1

            norm_lhs = _normalize_expr(lhs)
            norm_rhs = _normalize_expr(rhs)
            if norm_lhs and norm_rhs:
                if not _expr_has_identifier(lhs) and not _expr_has_identifier(rhs):
                    return False, "Boolean/Tautology injection detected: constant comparison"
                if norm_lhs == norm_rhs:
                    return False, "Boolean/Tautology injection detected: self-comparison tautology"

    for idx, (t_type, _, t_upper) in enumerate(code_tokens):
        if t_type == "WORD" and t_upper == "OR":
            j = idx + 1
            while j < m and (
                (code_tokens[j][0] == "PUNCT" and code_tokens[j][2] == "(")
                or (code_tokens[j][0] == "WORD" and code_tokens[j][2] == "NOT")
                or (code_tokens[j][0] == "OP" and code_tokens[j][2] in {"+", "-", "!"})
            ):
                j += 1
            if j < m:
                nt_type, _, nt_upper = code_tokens[j]
                if nt_type == "WORD" and nt_upper in {"TRUE", "FALSE"}:
                    return False, "Boolean/Tautology injection detected: OR boolean literal"
                if nt_type in {"NUMBER", "STRING"}:
                    after = j + 1
                    while after < m and code_tokens[after][0] == "PUNCT" and code_tokens[after][2] == ")":
                        after += 1
                    if (
                        after >= m
                        or (code_tokens[after][0] == "WORD" and code_tokens[after][2] in _CLAUSE_BOUNDARIES)
                        or code_tokens[after][0] == "SEMICOLON"
                    ):
                        return False, "Boolean/Tautology injection detected: OR constant truthy value"

    if has_leading_breakout:
        return False, "Boolean/Tautology injection detected: leading quote breakout"
    for cat, msg in issues:
        if cat in {"BREAKOUT", "UNCLOSED_QUOTE", "COMMENT"}:
            return False, msg

    return True, "SAFE"


def is_safe_sql_query(query: str) -> tuple[bool, str]:
    if not isinstance(query, str):
        return False, "Invalid query input"
    if "\x00" in query:
        return False, "Obfuscation / null byte injection detected"

    stripped = query.strip()
    if not stripped:
        return True, "SAFE"

    has_leading_breakout = False
    unwrapped = None

    # Exclude valid leading double-quoted column comparisons (e.g. `"status" = 'delayed'`)
    is_valid_dq_ident_start = bool(
        re.match(
            r'^"[a-zA-Z_][a-zA-Z0-9_]*"(?:\s*\.\s*"?[a-zA-Z_][a-zA-Z0-9_]*"?)?\s*'
            r"(?:=|!=|<>|<|>|<=|>=|->|->>|#>|#>>|\b(?:IN|LIKE|ILIKE|IS|BETWEEN)\b)",
            stripped,
            re.IGNORECASE,
        )
    )

    if not is_valid_dq_ident_start:
        m_lead = re.match(
            r'^\s*(?:([a-zA-Z_][a-zA-Z0-9_@.-]*|\d+(?:\.\d+)?))?\s*\\?([\'"])(.*)$',
            stripped,
            re.DOTALL,
        )
        if m_lead:
            prefix_word, quote_ch, rest = m_lead.group(1), m_lead.group(2), m_lead.group(3)
            if prefix_word is None or prefix_word.upper() not in _VALID_LEADING_KEYWORDS:
                has_leading_breakout = True
                unwrapped = re.sub(r"^\s*\)+", " ", rest)
                if unwrapped.endswith(quote_ch) and unwrapped.count(quote_ch) % 2 == 1:
                    unwrapped = unwrapped[:-1]

    tokens, issues = _tokenize_sql(stripped)

    if has_leading_breakout and unwrapped is not None:
        u_tokens, u_issues = _tokenize_sql(unwrapped)
        safe_u, reason_u = _analyze_token_stream(u_tokens, issues + u_issues, has_leading_breakout=True)
        if not safe_u:
            return False, reason_u

    return _analyze_token_stream(tokens, issues, has_leading_breakout=has_leading_breakout)
