from collections import OrderedDict
import threading
import time
from typing import Any, Optional


class _CacheEntry:
    __slots__ = ("value", "expiry")

    def __init__(self, value: Any, expiry: float) -> None:
        self.value = value
        self.expiry = expiry


class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("capacity must be greater than 0")
        if default_ttl_seconds <= 0:
            raise ValueError("default_ttl_seconds must be greater than 0")

        self.capacity: int = capacity
        self.default_ttl_seconds: float = default_ttl_seconds
        self._cache: OrderedDict[str, _CacheEntry] = OrderedDict()
        self._lock: threading.RLock = threading.RLock()
        self.lock: threading.RLock = self._lock

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self._lock:
            now = time.time()
            effective_ttl = ttl if ttl is not None else self.default_ttl_seconds
            expiry = now + effective_ttl

            if key in self._cache:
                self._cache[key] = _CacheEntry(value, expiry)
                self._cache.move_to_end(key)
                return

            if len(self._cache) >= self.capacity:
                expired_keys = [
                    k for k, node in self._cache.items() if now >= node.expiry
                ]
                if expired_keys:
                    evict_key = min(
                        expired_keys, key=lambda k: self._cache[k].expiry
                    )
                else:
                    evict_key = next(iter(self._cache))

                del self._cache[evict_key]

            self._cache[key] = _CacheEntry(value, expiry)

    def get(self, key: str) -> Optional[Any]:
        with self._lock:
            if key not in self._cache:
                return None

            node = self._cache[key]
            now = time.time()
            if now >= node.expiry:
                return None

            self._cache.move_to_end(key)
            return node.value

    def delete(self, key: str) -> bool:
        with self._lock:
            if key in self._cache:
                del self._cache[key]
                return True
            return False

    def cleanup_expired(self) -> int:
        with self._lock:
            now = time.time()
            expired_keys = [
                k for k, node in self._cache.items() if now >= node.expiry
            ]
            for k in expired_keys:
                del self._cache[k]
            return len(expired_keys)

    def size(self) -> int:
        with self._lock:
            now = time.time()
            return sum(1 for node in self._cache.values() if now < node.expiry)

    def __len__(self) -> int:
        return self.size()

    def __contains__(self, key: str) -> bool:
        with self._lock:
            if key not in self._cache:
                return False
            return time.time() < self._cache[key].expiry
