class CircularDependencyError(Exception):
    """Raised when a circular dependency is detected."""
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]] = None) -> list[list[str]]:
        """
        Resolves task dependencies into execution stages.

        :param dependencies: Mapping of task_name -> list of task_names it depends on.
        :return: List of stages, where each stage is a sorted list of task names.
        :raises CircularDependencyError: If a cycle or self-dependency is detected.
        """
        if dependencies is None:
            if isinstance(self, dict):
                dependencies = self
            else:
                dependencies = {}

        all_tasks = set(dependencies.keys())
        prereqs = {}
        for task, deps in dependencies.items():
            task_deps = set(deps)
            prereqs[task] = task_deps
            all_tasks.update(task_deps)

        if not all_tasks:
            return []

        adj = {task: [] for task in all_tasks}
        in_degree = {task: 0 for task in all_tasks}

        for task, deps in prereqs.items():
            in_degree[task] = len(deps)
            for dep in deps:
                adj[dep].append(task)

        # Stage 0: tasks with no dependencies
        current_stage = [task for task, deg in in_degree.items() if deg == 0]
        stages = []
        resolved_count = 0

        while current_stage:
            current_stage.sort()
            stages.append(current_stage)
            resolved_count += len(current_stage)

            next_stage = []
            for task in current_stage:
                for dependent in adj[task]:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        next_stage.append(dependent)
            current_stage = next_stage

        if resolved_count < len(all_tasks):
            raise CircularDependencyError("Circular dependency detected among tasks.")

        return stages
