import bisect
import collections
import threading
import time
from typing import Optional


class SlidingWindowRateLimiter:
    """Thread-safe sliding window rate limiter."""

    def __init__(self, max_requests: int, window_seconds: float):
        if max_requests < 0:
            raise ValueError("max_requests must be non-negative")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be positive")

        self.max_requests = max_requests
        self.window_seconds = float(window_seconds)
        self._lock = threading.RLock()
        self._windows: dict[str, collections.deque[float]] = {}

    def _clean_expired(self, key: str, now: float) -> Optional[collections.deque[float]]:
        """Evicts timestamps outside the sliding window (now - window_seconds, now]."""
        dq = self._windows.get(key)
        if dq is None:
            return None

        cutoff = now - self.window_seconds
        while dq and dq[0] <= cutoff:
            dq.popleft()

        if not dq:
            del self._windows[key]
            return None

        return dq

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        """Check if a request for the given key is allowed.

        Returns:
            (True, 0.0) if allowed.
            (False, retry_after) if rate limited.
        """
        with self._lock:
            now = time.time() if timestamp is None else float(timestamp)
            dq = self._clean_expired(key, now)

            if self.max_requests <= 0:
                return False, float(self.window_seconds)

            if dq is not None and len(dq) >= self.max_requests:
                idx = len(dq) - self.max_requests
                retry_after = (dq[idx] + self.window_seconds) - now
                return False, max(0.0, float(retry_after))

            if dq is None:
                dq = collections.deque()
                self._windows[key] = dq

            if dq and now < dq[-1]:
                bisect.insort(dq, now)
            else:
                dq.append(now)

            return True, 0.0

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        """Return the number of requests remaining in the current sliding window."""
        with self._lock:
            now = time.time() if timestamp is None else float(timestamp)
            dq = self._clean_expired(key, now)
            used = len(dq) if dq is not None else 0
            return max(0, self.max_requests - used)
