import asyncio
import inspect
from dataclasses import dataclass, field
from typing import Any, Optional


@dataclass(order=True)
class _PrioritizedItem:
    priority: int
    sequence: int
    coro_func: Any = field(compare=False)
    args: tuple = field(compare=False)
    kwargs: dict = field(compare=False)
    future: asyncio.Future = field(compare=False)


class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        if concurrency <= 0:
            raise ValueError("concurrency must be greater than 0")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be non-negative")

        self.concurrency: int = concurrency
        self.max_queue_size: int = max_queue_size
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: list[asyncio.Task] = []
        self._counter: int = 0
        self._started: bool = False
        self._is_shutting_down: bool = False
        self._is_shutdown: bool = False
        self._shutdown_event: asyncio.Event = asyncio.Event()

    async def start(self) -> None:
        if self._is_shutting_down or self._is_shutdown:
            raise RuntimeError("Pool is shutting down")
        if self._started:
            return

        self._started = True
        loop = asyncio.get_running_loop()
        self._workers = [
            loop.create_task(self._worker())
            for _ in range(self.concurrency)
        ]

    async def submit(self, coro_func, *args, priority: int = 0, **kwargs) -> asyncio.Future:
        if self._is_shutting_down or self._is_shutdown:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future = loop.create_future()
        self._counter += 1

        # Higher priority integer executes first; asyncio.PriorityQueue retrieves
        # lowest items first, so we store -priority. self._counter preserves FIFO for ties.
        item = _PrioritizedItem(
            priority=-priority,
            sequence=self._counter,
            coro_func=coro_func,
            args=args,
            kwargs=kwargs,
            future=future,
        )

        try:
            await self._queue.put(item)
        except asyncio.CancelledError:
            if not future.done():
                future.cancel()
            raise

        if self._is_shutting_down or self._is_shutdown:
            if not future.done():
                future.cancel()
            raise RuntimeError("Pool is shutting down")

        return future

    async def _worker(self) -> None:
        curr_task = asyncio.current_task()
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            if item.future.cancelled():
                if inspect.iscoroutine(item.coro_func):
                    item.coro_func.close()
                self._queue.task_done()
                continue

            def _on_future_cancel(f: asyncio.Future) -> None:
                if f.cancelled() and curr_task is not None:
                    curr_task.cancel()

            item.future.add_done_callback(_on_future_cancel)

            try:
                if callable(item.coro_func):
                    res = item.coro_func(*item.args, **item.kwargs)
                    if inspect.isawaitable(res):
                        res = await res
                elif inspect.isawaitable(item.coro_func):
                    res = await item.coro_func
                else:
                    raise TypeError(f"Expected callable or awaitable, got {type(item.coro_func)}")

                if not item.future.done():
                    item.future.set_result(res)
            except asyncio.CancelledError:
                if not item.future.done():
                    item.future.cancel()
                if self._is_shutting_down:
                    break
                # If cancellation was triggered solely for this task, uncancel the worker
                if curr_task is not None and hasattr(curr_task, "uncancel"):
                    curr_task.uncancel()
            except Exception as exc:
                if not item.future.done():
                    item.future.set_exception(exc)
            except BaseException as exc:
                if not item.future.done():
                    item.future.set_exception(exc)
                raise
            finally:
                item.future.remove_done_callback(_on_future_cancel)
                self._queue.task_done()

    def _cancel_pending_tasks(self) -> None:
        while not self._queue.empty():
            try:
                item = self._queue.get_nowait()
                if not item.future.done():
                    item.future.cancel()
                if inspect.iscoroutine(item.coro_func):
                    item.coro_func.close()
                self._queue.task_done()
            except asyncio.QueueEmpty:
                break

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        if self._is_shutdown:
            return
        if self._is_shutting_down:
            await self._shutdown_event.wait()
            return

        self._is_shutting_down = True
        loop = asyncio.get_running_loop()
        start_time = loop.time()

        def remaining_timeout() -> Optional[float]:
            if timeout is None:
                return None
            elapsed = loop.time() - start_time
            return max(0.0, timeout - elapsed)

        try:
            if drain:
                if not self._started and not self._queue.empty():
                    await self.start()
                if timeout is not None:
                    try:
                        await asyncio.wait_for(self._queue.join(), timeout=remaining_timeout())
                    except (asyncio.TimeoutError, TimeoutError):
                        self._cancel_pending_tasks()
                else:
                    await self._queue.join()
            else:
                self._cancel_pending_tasks()
        finally:
            for worker in self._workers:
                if not worker.done():
                    worker.cancel()

            if self._workers:
                try:
                    rem = remaining_timeout()
                    if rem is not None:
                        await asyncio.wait_for(
                            asyncio.gather(*self._workers, return_exceptions=True),
                            timeout=rem,
                        )
                    else:
                        await asyncio.gather(*self._workers, return_exceptions=True)
                except (asyncio.TimeoutError, TimeoutError):
                    pass

            self._is_shutdown = True
            self._is_shutting_down = False
            self._shutdown_event.set()

    async def __aenter__(self):
        await self.start()
        return self

    async def __aexit__(self, exc_type, exc_val, exc_tb):
        await self.shutdown(drain=True)
