from typing import Any, Optional


class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        """
        Initializes cluster state with given unique node IDs.
        Total node count N = len(node_ids). Quorum threshold is floor(N / 2) + 1.
        """
        self.node_ids: list[str] = list(node_ids)
        self._node_set: set[str] = set(node_ids)
        self.n: int = len(self.node_ids)
        self.N: int = self.n
        self.quorum_threshold: int = self.n // 2 + 1
        self.threshold: int = self.quorum_threshold
        self.quorum: int = self.quorum_threshold

        # Node storage: node_id -> {key: value}
        self.node_states: dict[str, dict[str, Any]] = {nid: {} for nid in self.node_ids}
        self.nodes: dict[str, dict[str, Any]] = self.node_states

        # Cluster committed state and logical clock for version tracking
        self._committed_state: dict[str, Any] = {}
        self._key_versions: dict[str, int] = {}
        self._node_key_versions: dict[str, dict[str, int]] = {nid: {} for nid in self.node_ids}
        self._clock: int = 0

        # Network partitioning state: None represents fully connected cluster
        self._node_to_partition: Optional[dict[str, set[str]]] = None

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """
        Divides cluster into isolated network partitions where nodes in
        group_a can only talk to group_a, and group_b only to group_b.
        """
        set_a = set(group_a) & self._node_set
        set_b = set(group_b) & self._node_set
        self._node_to_partition = {}
        for node in set_a:
            self._node_to_partition[node] = set_a
        for node in set_b:
            self._node_to_partition[node] = set_b
        # Any remaining cluster nodes not in group_a or group_b are isolated
        for node in self.node_ids:
            if node not in self._node_to_partition:
                self._node_to_partition[node] = {node}

    def heal_partition(self) -> None:
        """
        Restores full connectivity so all nodes can communicate,
        synchronizing committed state across all nodes.
        """
        self._node_to_partition = None

        # Synchronize committed state across all nodes
        for nid in self.node_ids:
            for k, v in self.node_states[nid].items():
                ver = self._node_key_versions[nid].get(k, 0)
                if ver >= self._key_versions.get(k, 0):
                    self._committed_state[k] = v
                    self._key_versions[k] = ver

        for nid in self.node_ids:
            self.node_states[nid] = dict(self._committed_state)
            self._node_key_versions[nid] = dict(self._key_versions)

    def _get_active_partition(self, node: str) -> set[str]:
        if node not in self._node_set:
            return set()
        if self._node_to_partition is None:
            return set(self.node_ids)
        return self._node_to_partition.get(node, {node})

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """
        Proposes a write from from_node.
        If from_node belongs to a partition having a STRICT MAJORITY
        (active partition size >= quorum threshold), the write commits,
        updates state in all nodes within that partition, and returns True.
        If from_node is in a MINORITY partition (< quorum threshold),
        the write is REJECTED (returns False).
        """
        active_partition = self._get_active_partition(from_node)
        if len(active_partition) < self.quorum_threshold:
            return False

        self._clock += 1
        self._committed_state[key] = value
        self._key_versions[key] = self._clock

        for node in active_partition:
            self.node_states[node][key] = value
            self._node_key_versions[node][key] = self._clock

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        """
        Returns the committed value for key on from_node (or None if not set).
        """
        if from_node not in self.node_states:
            return None
        return self.node_states[from_node].get(key, None)
