import ast
import re


def prune_dead_code_and_imports(source_code: str) -> str:
    """Prune unused imports and dead top-level private functions from Python source code.

    Guarantees:
    - Prunes unused `import` statements and unused names from `from ... import ...` statements.
    - Removes top-level private functions (names starting with `_`) if unreferenced elsewhere.
    - Preserves module docstrings, class definitions, and global variable assignments.
    - Preserves public functions (names not starting with `_`).
    - Returns valid Python code that compiles via `compile()`.
    """
    tree = ast.parse(source_code)

    def is_private_function(stmt: ast.AST) -> bool:
        return (
            isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef))
            and stmt.name.startswith("_")
        )

    def extract_names_from_annotation(node: ast.AST) -> set[str]:
        names = set()
        for child in ast.walk(node):
            if isinstance(child, ast.Name):
                names.add(child.id)
            elif isinstance(child, ast.Constant) and isinstance(child.value, str):
                try:
                    sub_tree = ast.parse(child.value, mode="eval")
                    names.update(
                        n.id for n in ast.walk(sub_tree) if isinstance(n, ast.Name)
                    )
                except Exception:
                    names.update(re.findall(r"\b[A-Za-z_][A-Za-z0-9_]*\b", child.value))
        return names

    def get_names_in_node(node: ast.AST) -> set[str]:
        names = set()
        for child in ast.walk(node):
            if isinstance(child, ast.Name):
                names.add(child.id)
            elif isinstance(child, (ast.Global, ast.Nonlocal)):
                names.update(child.names)

            # Type comments support
            type_comment = getattr(child, "type_comment", None)
            if isinstance(type_comment, str):
                names.update(re.findall(r"\b[A-Za-z_][A-Za-z0-9_]*\b", type_comment))

            # String type annotations or forward references
            if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if child.returns:
                    names.update(extract_names_from_annotation(child.returns))
            elif isinstance(child, ast.arg):
                if child.annotation:
                    names.update(extract_names_from_annotation(child.annotation))
            elif isinstance(child, ast.AnnAssign):
                if child.annotation:
                    names.update(extract_names_from_annotation(child.annotation))
            elif hasattr(ast, "TypeAlias") and isinstance(child, ast.TypeAlias):
                names.update(extract_names_from_annotation(child.value))

            # Exported names declared in __all__
            if isinstance(child, ast.Assign):
                for target in child.targets:
                    if isinstance(target, ast.Name) and target.id == "__all__":
                        for elt in ast.walk(child.value):
                            if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                                names.add(elt.value)
            elif isinstance(child, ast.AugAssign):
                if isinstance(child.target, ast.Name) and child.target.id == "__all__":
                    for elt in ast.walk(child.value):
                        if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                            names.add(elt.value)
        return names

    # 1. Separate roots, private functions, and imports in the top-level AST body
    private_funcs: list[ast.AST] = []
    roots: list[ast.AST] = []
    for stmt in tree.body:
        if is_private_function(stmt):
            private_funcs.append(stmt)
        elif isinstance(stmt, (ast.Import, ast.ImportFrom)):
            pass
        else:
            roots.append(stmt)

    # 2. Reachability analysis for private functions starting from roots
    live_names = set()
    for stmt in roots:
        live_names.update(get_names_in_node(stmt))

    alive_private_nodes = set()
    queue = [fn for fn in private_funcs if getattr(fn, "name", "") in live_names]
    alive_private_nodes.update(queue)

    while queue:
        curr = queue.pop(0)
        curr_refs = get_names_in_node(curr)
        for fn in private_funcs:
            fn_name = getattr(fn, "name", "")
            if fn not in alive_private_nodes and fn_name in curr_refs:
                alive_private_nodes.add(fn)
                queue.append(fn)

    # 3. Determine all used names across all retained non-import statements
    retained_non_imports = roots + [fn for fn in private_funcs if fn in alive_private_nodes]
    all_used_names = set()
    for stmt in retained_non_imports:
        all_used_names.update(get_names_in_node(stmt))

    # 4. Prune unused imports and reconstruct tree.body
    new_body = []
    for stmt in tree.body:
        if is_private_function(stmt):
            if stmt in alive_private_nodes:
                new_body.append(stmt)
        elif isinstance(stmt, ast.Import):
            kept_names = []
            for alias in stmt.names:
                bound_name = alias.asname or alias.name.split(".")[0]
                if bound_name in all_used_names:
                    kept_names.append(alias)
            if kept_names:
                stmt.names = kept_names
                new_body.append(stmt)
        elif isinstance(stmt, ast.ImportFrom):
            if stmt.module == "__future__":
                new_body.append(stmt)
            else:
                kept_names = []
                for alias in stmt.names:
                    bound_name = alias.asname or alias.name
                    if bound_name in all_used_names or alias.name == "*":
                        kept_names.append(alias)
                if kept_names:
                    stmt.names = kept_names
                    new_body.append(stmt)
        else:
            new_body.append(stmt)

    tree.body = new_body
    result = ast.unparse(tree)
    compile(result, "<string>", "exec")
    return result
