import os
import stat
import unicodedata
import zipfile
from pathlib import Path, PurePosixPath, PureWindowsPath


def safe_extract_zip(
    archive_path: str,
    destination: str,
    max_files: int = 1000,
    max_uncompressed_bytes: int = 10000000,
    max_compression_ratio: float = 100.0,
) -> list[str]:
    def is_abs(name: str) -> bool:
        if not name:
            return False
        if name.startswith(("/", "\\")):
            return True
        pw = PureWindowsPath(name)
        if pw.is_absolute() or pw.drive or pw.root:
            return True
        pp = PurePosixPath(name)
        if pp.is_absolute() or pp.root:
            return True
        return False

    def is_dir_entry(info: zipfile.ZipInfo, name: str) -> bool:
        if info.is_dir():
            return True
        if name.endswith(("/", "\\")):
            return True
        if stat.S_ISDIR(info.external_attr >> 16):
            return True
        return False

    dest_path = Path(destination).resolve()

    try:
        zf = zipfile.ZipFile(archive_path, "r")
    except zipfile.BadZipFile as e:
        raise ValueError(f"Invalid zip archive: {e}") from e

    with zf:
        infolist = zf.infolist()
        seen_nfc_filenames = set()
        seen_file_paths = set()
        seen_dir_paths = set()
        implicit_dirs = set()
        file_entries = []
        dir_entries = []
        total_uncompressed = 0

        # Phase 1: Validate the entire archive before writing anything
        for info in infolist:
            raw_name = info.filename
            orig_name = getattr(info, "orig_filename", raw_name)
            if not isinstance(orig_name, str):
                orig_name = str(orig_name)

            # 1. NUL byte check
            if "\x00" in raw_name or "\x00" in orig_name:
                raise ValueError(f"Entry contains NUL byte: {raw_name!r}")

            # 2. Absolute path check
            if is_abs(raw_name) or is_abs(orig_name):
                raise ValueError(f"Entry is absolute: {raw_name!r}")

            # 3. Unix symlink check
            mode = info.external_attr >> 16
            if stat.S_ISLNK(mode):
                raise ValueError(f"Entry is a Unix symlink: {raw_name!r}")

            # 4. Escapes through '..' using either slash style
            for check_name in (raw_name, orig_name):
                posix_style = check_name.replace("\\", "/")
                raw_parts = posix_style.split("/")
                resolved = []
                for p in raw_parts:
                    if p == "" or p == ".":
                        continue
                    elif p == "..":
                        if not resolved:
                            raise ValueError(f"Entry escapes through '..': {raw_name!r}")
                        resolved.pop()
                    else:
                        resolved.append(p)
                if not resolved:
                    raise ValueError(f"Entry resolves to root: {raw_name!r}")

            # 5. Unicode NFC normalization collision checks
            nfc_raw = unicodedata.normalize("NFC", raw_name)
            if nfc_raw in seen_nfc_filenames:
                raise ValueError(f"Entry collides after Unicode NFC normalization: {raw_name!r}")
            seen_nfc_filenames.add(nfc_raw)

            # Compute normalized POSIX relative path with NFC normalized components
            nfc_posix = nfc_raw.replace("\\", "/")
            parts = [p for p in nfc_posix.split("/") if p and p != "."]
            resolved_parts = []
            for p in parts:
                if p == "..":
                    if not resolved_parts:
                        raise ValueError(f"Entry escapes through '..': {raw_name!r}")
                    resolved_parts.pop()
                else:
                    resolved_parts.append(unicodedata.normalize("NFC", p))

            if not resolved_parts:
                raise ValueError(f"Entry resolves to root: {raw_name!r}")

            norm_posix_path = "/".join(resolved_parts)

            # Check containment strictly beneath destination
            target_path = (dest_path / norm_posix_path).resolve()
            try:
                target_path.relative_to(dest_path)
            except ValueError:
                raise ValueError(f"Entry escapes destination: {raw_name!r}")
            if target_path == dest_path:
                raise ValueError(f"Entry resolves to destination root: {raw_name!r}")

            # Directory vs file handling
            is_directory = is_dir_entry(info, raw_name)

            if is_directory:
                if norm_posix_path in seen_file_paths:
                    raise ValueError(f"Directory collides with existing file: {norm_posix_path}")
                if norm_posix_path in seen_dir_paths:
                    raise ValueError(f"Duplicate directory entry: {norm_posix_path}")
                seen_dir_paths.add(norm_posix_path)
                dir_entries.append((info, norm_posix_path))
            else:
                if norm_posix_path in seen_file_paths:
                    raise ValueError(f"Entry collides after Unicode NFC normalization: {norm_posix_path}")
                if norm_posix_path in seen_dir_paths or norm_posix_path in implicit_dirs:
                    raise ValueError(f"File collides with directory: {norm_posix_path}")

                # Check if any parent component of this file is already a file
                parent_parts = resolved_parts[:-1]
                for i in range(1, len(parent_parts) + 1):
                    parent_path = "/".join(parent_parts[:i])
                    if parent_path in seen_file_paths:
                        raise ValueError(f"File path parent collides with file: {parent_path}")
                    implicit_dirs.add(parent_path)

                seen_file_paths.add(norm_posix_path)
                file_entries.append((info, norm_posix_path))

                # Check per-file compression ratio
                if info.compress_size < 0 or info.file_size < 0:
                    raise ValueError(f"Negative size in archive entry: {raw_name!r}")
                if info.compress_size == 0:
                    if info.file_size > 0:
                        raise ValueError(
                            f"Per-file compression ratio exceeds {max_compression_ratio} (infinite)"
                        )
                else:
                    ratio = info.file_size / info.compress_size
                    if ratio > max_compression_ratio:
                        raise ValueError(
                            f"Per-file compression ratio ({ratio}) exceeds {max_compression_ratio}"
                        )

            total_uncompressed += info.file_size

        # 6. File count limit (directories do not count as files)
        if len(file_entries) > max_files:
            raise ValueError(f"File count ({len(file_entries)}) exceeds limit ({max_files})")

        # 7. Cumulative uncompressed bytes limit
        if total_uncompressed > max_uncompressed_bytes:
            raise ValueError(
                f"Cumulative uncompressed bytes ({total_uncompressed}) exceeds limit ({max_uncompressed_bytes})"
            )

        # Phase 2: Extraction beneath destination (only reached if all entries are valid)
        dest_path.mkdir(parents=True, exist_ok=True)

        for info, norm_path in dir_entries:
            target_dir = dest_path / norm_path
            target_dir.mkdir(parents=True, exist_ok=True)

        extracted_files = []
        for info, norm_path in file_entries:
            target_file = dest_path / norm_path
            target_file.parent.mkdir(parents=True, exist_ok=True)
            with zf.open(info, "r") as src, open(target_file, "wb") as dst:
                while True:
                    chunk = src.read(65536)
                    if not chunk:
                        break
                    dst.write(chunk)
            extracted_files.append(norm_path)

        return sorted(extracted_files)
