import fnmatch


def authorize(request: dict, policies: list[dict]) -> bool:
    if not isinstance(request, dict):
        return False
    if not isinstance(policies, list):
        return False

    for field in (
        "subject_id",
        "tenant_id",
        "resource_tenant_id",
        "action",
        "resource",
    ):
        val = request.get(field)
        if not isinstance(val, str) or len(val) == 0:
            return False

    if request["tenant_id"] != request["resource_tenant_id"]:
        return False

    roles = request.get("roles")
    if not isinstance(roles, list) or len(roles) == 0:
        return False
    if not all(isinstance(r, str) and len(r) > 0 for r in roles):
        return False

    context = request.get("context")
    if not isinstance(context, dict):
        return False

    for policy in policies:
        if not isinstance(policy, dict):
            return False
        if policy.get("effect") not in ("allow", "deny"):
            return False
        tenant = policy.get("tenant")
        if not isinstance(tenant, str) or len(tenant) == 0:
            return False
        p_roles = policy.get("roles")
        if not isinstance(p_roles, list) or len(p_roles) == 0:
            return False
        if not all(isinstance(r, str) and len(r) > 0 for r in p_roles):
            return False
        p_actions = policy.get("actions")
        if not isinstance(p_actions, list) or len(p_actions) == 0:
            return False
        if not all(isinstance(a, str) and len(a) > 0 for a in p_actions):
            return False
        p_resources = policy.get("resources")
        if not isinstance(p_resources, list) or len(p_resources) == 0:
            return False
        if not all(isinstance(res, str) and len(res) > 0 for res in p_resources):
            return False
        if "conditions" in policy:
            if not isinstance(policy["conditions"], dict):
                return False

    req_tenant = request["tenant_id"]
    req_roles = request["roles"]
    req_action = request["action"]
    req_resource = request["resource"]

    has_allow = False

    for policy in policies:
        pol_tenant = policy["tenant"]
        if pol_tenant != "*" and pol_tenant != req_tenant:
            continue

        pol_roles = policy["roles"]
        if "*" not in pol_roles and "*" not in req_roles:
            if not any(r in pol_roles for r in req_roles):
                continue

        if not any(
            fnmatch.fnmatchcase(req_action, pat) for pat in policy["actions"]
        ):
            continue

        if not any(
            fnmatch.fnmatchcase(req_resource, pat) for pat in policy["resources"]
        ):
            continue

        if "conditions" in policy:
            cond_mismatch = False
            for cond_key, cond_val in policy["conditions"].items():
                if cond_key not in context:
                    cond_mismatch = True
                    break
                ctx_val = context[cond_key]
                if isinstance(cond_val, list):
                    try:
                        if ctx_val not in cond_val and ctx_val != cond_val:
                            cond_mismatch = True
                            break
                    except TypeError:
                        if ctx_val != cond_val:
                            cond_mismatch = True
                            break
                else:
                    if ctx_val != cond_val:
                        cond_mismatch = True
                        break
            if cond_mismatch:
                continue

        if policy["effect"] == "deny":
            return False
        else:
            has_allow = True

    return has_allow
