class RetryableError(Exception):
    pass


class FatalError(Exception):
    pass


class CrashError(Exception):
    pass


class SagaOrchestrator:
    def __init__(
        self,
        executor,
        compensator,
        max_retries: int = 2,
        journal: dict | None = None,
    ):
        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        self.journal = {} if journal is None else journal

    def _validate(self, saga_id: str, steps: list[str]) -> None:
        if not isinstance(saga_id, str) or not saga_id:
            raise ValueError("saga_id must be a non-empty string")
        if not isinstance(steps, list) or len(steps) == 0:
            raise ValueError("steps must be a non-empty list of unique non-empty strings")
        for step in steps:
            if not isinstance(step, str) or not step:
                raise ValueError("each step must be a non-empty string")
        if len(steps) != len(set(steps)):
            raise ValueError("steps must be unique")

        if saga_id in self.journal:
            entry = self.journal[saga_id]
            if isinstance(entry, dict):
                stored_steps = entry.get("steps")
                if stored_steps is not None:
                    if list(stored_steps) != list(steps):
                        raise ValueError(f"Step plan changed for existing saga '{saga_id}'")
                else:
                    completed = entry.get("completed", [])
                    if any(c not in steps for c in completed) or steps[:len(completed)] != list(completed):
                        raise ValueError(f"Step plan changed for existing saga '{saga_id}'")
            elif isinstance(entry, (list, tuple)):
                if list(entry) != list(steps):
                    raise ValueError(f"Step plan changed for existing saga '{saga_id}'")

    def _get_or_create_entry(self, saga_id: str, steps: list[str]) -> dict:
        if saga_id not in self.journal:
            self.journal[saga_id] = {
                "steps": list(steps),
                "completed": [],
                "compensated": [],
                "status": "running",
                "state": "running",
                "compensating": False,
            }
        entry = self.journal[saga_id]
        if isinstance(entry, dict):
            entry.setdefault("steps", list(steps))
            entry.setdefault("completed", [])
            entry.setdefault("compensated", [])
            entry.setdefault("status", "running")
            entry.setdefault("state", entry.get("status", "running"))
            entry.setdefault("compensating", entry.get("status") == "compensating")
            if not isinstance(entry["completed"], list):
                entry["completed"] = list(entry["completed"])
            if not isinstance(entry["compensated"], list):
                entry["compensated"] = list(entry["compensated"])
            if not isinstance(entry["steps"], list):
                entry["steps"] = list(entry["steps"])
        return entry

    def _is_compensating(self, entry: dict) -> bool:
        if entry.get("status") in ("compensating", "compensated"):
            return True
        if entry.get("state") in ("compensating", "compensated"):
            return True
        if bool(entry.get("compensating")):
            return True
        compensated = entry.get("compensated", [])
        if len(compensated) > 0:
            return True
        return False

    def _compensate(self, entry: dict) -> str:
        entry["status"] = "compensating"
        entry["state"] = "compensating"
        entry["compensating"] = True

        completed = entry["completed"]
        compensated_set = set(entry["compensated"])

        for step in reversed(completed):
            if step in compensated_set:
                continue

            attempts = 0
            while True:
                try:
                    self.compensator(step)
                    break
                except CrashError:
                    raise
                except RetryableError:
                    if attempts < self.max_retries:
                        attempts += 1
                        continue
                    raise

            entry["compensated"].append(step)
            compensated_set.add(step)

        entry["status"] = "compensated"
        entry["state"] = "compensated"
        entry["compensating"] = False
        return "compensated"

    def _execute_saga(self, saga_id: str, steps: list[str]) -> str:
        self._validate(saga_id, steps)
        entry = self._get_or_create_entry(saga_id, steps)

        if self._is_compensating(entry):
            return self._compensate(entry)

        completed_set = set(entry["completed"])

        for step in steps:
            if step in completed_set:
                continue

            failed = False
            attempts = 0
            while True:
                try:
                    self.executor(step)
                    break
                except CrashError:
                    raise
                except RetryableError:
                    if attempts < self.max_retries:
                        attempts += 1
                        continue
                    failed = True
                    break
                except FatalError:
                    failed = True
                    break
                except Exception:
                    failed = True
                    break

            if failed:
                return self._compensate(entry)

            entry["completed"].append(step)
            completed_set.add(step)

        entry["status"] = "completed"
        entry["state"] = "completed"
        entry["compensating"] = False
        return "completed"

    def run(self, saga_id: str, steps: list[str]) -> str:
        return self._execute_saga(saga_id, steps)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        return self._execute_saga(saga_id, steps)
